validator:
function validate(input) {
  const [{ SeasonStats = [] }] = input;
  const keys = new Set(), names = new Set();
  for (const row of SeasonStats) {
    if (row.some((v) => v === null)) return 'SeasonStats rows may not contain null.';
    const [season, team, name, , wins, draws, losses, scored, conceded] = row;
    if (keys.has(`${season}|${team}`)) return `Team ${team} appears twice in season ${season}.`;
    keys.add(`${season}|${team}`);
    const nameKey = `${season}|${String(name).toLowerCase()}`;
    if (names.has(nameKey)) return `team_name ${name} appears twice in season ${season}.`;
    names.add(nameKey);
    if (wins < 0 || draws < 0 || losses < 0 || scored < 0 || conceded < 0) return `Team ${team} in season ${season} has a negative count.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const SeasonStats = [];
  const record = (season, team, name, maxCount, maxGoals) => {
    const wins = pick(maxCount + 1), draws = pick(maxCount + 1), losses = pick(maxCount + 1);
    SeasonStats.push([season, team, name, wins + draws + losses, wins, draws, losses, pick(maxGoals + 1), pick(maxGoals + 1)]);
  };
  if (size === 'small') {
    // Team ids are deliberately not in alphabetical order of their names.
    const names = ['Wolves', 'Arsenal', 'Everton', 'Chelsea', 'Brighton', 'Fulham'];
    const seasons = [2021, 2022, 2023];
    const target = pick(9);
    const used = new Set();
    for (let tries = 0; tries < 40 && SeasonStats.length < target; tries++) {
      const season = seasons[pick(seasons.length)], team = 1 + pick(names.length);
      if (used.has(`${season}|${team}`)) continue;
      used.add(`${season}|${team}`);
      record(season, team, names[team - 1], 3, 5);
    }
    return [{ SeasonStats }];
  }
  // 50 seasons of 40 teams; small ranges make points and goal-difference ties common.
  const teams = 40;
  for (let season = 2049; season >= 2000; season--) {
    for (let team = 1; team <= teams; team++) {
      record(season, team, `Team ${String((team * 17) % teams).padStart(2, '0')}`, 5, 10);
    }
  }
  return [{ SeasonStats }];
}
